INSERT INTO `launcher_news` VALUES
(2,'AetherXIV v1.3 Servers Now in Testing!','Testers:','New server tools and gameplay improvements, including the new !pinspawn GM command - You can use this to mark where a known enemy should be in a zone. This helps to restore known enemy spawns. Restored base stat logic, and other fixes for session states are coming soon.','','','2026-07-07 01:55:00',1,0);
